function onChange(value, rowNum, parentRowNum) {
  /* mk-migrate:view-status=add,edit */
  if (MKXFORM.viewStatus != "add" && MKXFORM.viewStatus != "edit") return;
  var selectedValue = Array.isArray(value) ? value[0] : value
  var active = String(selectedValue) === "gh"
  MKXFORM.updateControl("${table:fd_detail}.fd_hidden", rowNum, active ? "true" : "")
  MKXFORM.updateControlStyle("${table:fd_detail}.fd_notes", rowNum, { display: active ? "block" : "none" })
  MKXFORM.setDetailFieldItemAttr("${table:fd_detail}", active ? 5 : 4, rowNum, "${table:fd_detail}.fd_notes")
  MKXFORM.setDetailFieldItemAttr("${table:fd_detail}", active ? 3 : 6, rowNum, "${table:fd_detail}.fd_notes")
}

function onLoad() {
  var rows = MKXFORM.getValue("${table:fd_detail}") || []
  for (var rowNum = 0; rowNum < rows.length; rowNum += 1) {
    var active = String(rows[rowNum]["fd_choice"] || "") === "gh" || String(rows[rowNum]["fd_hidden"] || "") === "true"
    MKXFORM.updateControl("${table:fd_detail}.fd_hidden", rowNum, active ? "true" : "")
    MKXFORM.updateControlStyle("${table:fd_detail}.fd_notes", rowNum, { display: active ? "block" : "none" })
    MKXFORM.setDetailFieldItemAttr("${table:fd_detail}", active ? 5 : 4, rowNum, "${table:fd_detail}.fd_notes")
    MKXFORM.setDetailFieldItemAttr("${table:fd_detail}", active ? 3 : 6, rowNum, "${table:fd_detail}.fd_notes")
  }
}
